<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free QR Text Generator','description'=>'Generate a QR code from any text directly in your browser.','url'=>'https://smarttoolz.in/tools/qr-text-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>QR Text Generator</h1><p>Create a QR code from text or a URL.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="i" placeholder="Enter text or URL"><button id="go" class="tool-btn">Generate QR</button><div id="o"></div></div></section></main><script>go.onclick=()=>{let v=encodeURIComponent(i.value);o.innerHTML=v?`<img alt="QR code" width="220" height="220" src="https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=${v}">`:'Enter text first.'}</script><?php smarttoolz_tool_page_end(); ?>